#include <fstream>
#include <string>
#include <iostream>
#include <exception>

class FileWrapper {  // RAII class for managing a file
private:
    std::ofstream fileStream;  // File stream as the resource

public:
    FileWrapper(const std::string& filename) {  // Constructor acquires the resource
        fileStream.open(filename);
        if (!fileStream.is_open()) {
            throw std::runtime_error("Failed to open file: " + filename);
        }
        std::cout << "File opened successfully." << std::endl;
    }

    ~FileWrapper() {  // Destructor releases the resource
        if (fileStream.is_open()) {
            fileStream.close();
            std::cout << "File closed automatically." << std::endl;
        }
    }

    // Additional method for practical usage
    void writeToFile(const std::string& data) {
        if (fileStream.is_open()) {
            fileStream << data << std::endl;
        }
    }
};

int main() {
    try {
        FileWrapper fw("example.txt");  // Object creation acquires the resource
        fw.writeToFile("Hello, RAII!");  // Use the resource
        // No explicit close needed; destructor handles it when fw goes out of scope
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
    return 0;  // fw's destructor is called here, ensuring cleanup
}
